package net.officefloor.hq.app.role;

import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** Roles by sheet: at most one per user name; a name with none is a clerk. */
@Repository
public class RoleRepository {

    private static final RowMapper<Role> ROW = (rs, i) -> new Role(rs.getString("sheet_id"),
            rs.getString("user_name"), rs.getString("role"));

    private final JdbcTemplate jdbc;

    public RoleRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's assigned roles, by user name. */
    public List<Role> list(String sheetId) {
        return jdbc.query("SELECT * FROM sheet_role WHERE sheet_id = ? ORDER BY user_name", ROW, sheetId);
    }

    /** The role the user acts in on the sheet: steward while a delegation to them is in force by the sheet's
     *  today, else the one assigned. */
    public String of(String sheetId, String user) {
        Integer delegated = jdbc.queryForObject("SELECT COUNT(*) FROM sheet_delegation d JOIN sheet s "
                + "ON s.id = d.sheet_id WHERE d.sheet_id = ? AND d.user_name = ? "
                + "AND s.today BETWEEN d.from_date AND d.to_date", Integer.class, sheetId, user);
        return delegated != null && delegated > 0 ? Role.STEWARD : assigned(sheetId, user);
    }

    /** The user's assigned role on the sheet: the one assigned, else clerk. */
    public String assigned(String sheetId, String user) {
        List<String> found = jdbc.queryForList("SELECT role FROM sheet_role WHERE sheet_id = ? AND user_name = ?",
                String.class, sheetId, user);
        return found.isEmpty() ? Role.CLERK : found.get(0);
    }

    /** Assign the user's role on the sheet, replacing any they had. */
    public Role set(String sheetId, String user, String role) {
        jdbc.update("MERGE INTO sheet_role KEY (sheet_id, user_name) VALUES (?, ?, ?)", sheetId, user, role);
        return new Role(sheetId, user, role);
    }
}
package net.officefloor.hq.app.role;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ReadListener;
import jakarta.servlet.ServletException;
import jakarta.servlet.ServletInputStream;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletRequestWrapper;
import jakarta.servlet.http.HttpServletResponse;
import java.io.BufferedReader;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;
import tools.jackson.databind.json.JsonMapper;

/** Refuse every change a viewer asks for on a sheet, and every change to an archived sheet, before any endpoint
 *  reads or writes anything: each POST or PUT under a sheet (all but loading the sheet itself) whose signed-in user
 *  (the body's {@code user}) is a viewer on that sheet, or on a sheet that is archived, is answered 403 with the
 *  reason, and nothing is written or audited. A bulk open is left to its endpoint, which counts every selected claim
 *  refused for a viewer or on an archived sheet; so is a bulk settle on an archived sheet. */
@Component
public class RefuseViewerChanges extends OncePerRequestFilter {

    /** A change under a sheet: /api/sheets/{sheetId}/... (loading the sheet, /api/sheets/{sheetId}, is not one). */
    private static final Pattern CHANGE = Pattern.compile("^/api/sheets/([^/]+)/.+$");

    /** A bulk open, left to the endpoint: it refuses each selected claim a viewer's role may not open (none), and
     *  answers how many it opened and refused, writing nothing. */
    private static final Pattern BULK_OPEN = Pattern.compile("^/api/sheets/[^/]+/bulk-open$");

    /** A bulk settle, left to the endpoint on an archived sheet: it counts every selected claim refused. */
    private static final Pattern BULK_SETTLE = Pattern.compile("^/api/sheets/[^/]+/bulk-settle$");

    private final RoleRepository roles;
    private final SheetRepository sheets;
    private final JsonMapper json = JsonMapper.builder().build();

    public RefuseViewerChanges(RoleRepository roles, SheetRepository sheets) {
        this.roles = roles;
        this.sheets = sheets;
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
            throws ServletException, IOException {
        String method = request.getMethod();
        String path = request.getRequestURI().substring(request.getContextPath().length());
        Matcher change = CHANGE.matcher(path);
        if (method.equals("GET") || method.equals("HEAD") || method.equals("OPTIONS") || !change.matches()
                || BULK_OPEN.matcher(path).matches()) {
            chain.doFilter(request, response);
            return;
        }
        byte[] body = request.getInputStream().readAllBytes();
        String sheetId = URLDecoder.decode(change.group(1), StandardCharsets.UTF_8).trim();
        String user = user(body);
        if (user != null && Role.VIEWER.equals(roles.of(sheetId, user))) {
            response.setStatus(HttpServletResponse.SC_FORBIDDEN);
            response.setContentType("text/plain;charset=UTF-8");
            response.getWriter().write("A viewer can change nothing on this sheet.");
            return;
        }
        if (!BULK_SETTLE.matcher(path).matches() && sheets.archived(sheetId)) {
            response.setStatus(HttpServletResponse.SC_FORBIDDEN);
            response.setContentType("text/plain;charset=UTF-8");
            response.getWriter().write("This sheet is archived: nothing on it can be changed.");
            return;
        }
        chain.doFilter(new Rereadable(request, body), response);
    }

    /** The signed-in user the body names (trimmed), or null when there is none. */
    private String user(byte[] body) {
        try {
            Object user = json.readValue(body, Map.class).get("user");
            return user instanceof String name && !name.isBlank() ? name.trim() : null;
        } catch (RuntimeException e) {
            return null; // not a JSON object: left to the endpoint to refuse
        }
    }

    /** The request with its body, already read here, readable again by the endpoint. */
    private static final class Rereadable extends HttpServletRequestWrapper {
        private final byte[] body;

        Rereadable(HttpServletRequest request, byte[] body) {
            super(request);
            this.body = body;
        }

        @Override
        public ServletInputStream getInputStream() {
            ByteArrayInputStream in = new ByteArrayInputStream(body);
            return new ServletInputStream() {
                @Override
                public int read() {
                    return in.read();
                }

                @Override
                public int read(byte[] b, int off, int len) {
                    return in.read(b, off, len);
                }

                @Override
                public boolean isFinished() {
                    return in.available() == 0;
                }

                @Override
                public boolean isReady() {
                    return true;
                }

                @Override
                public void setReadListener(ReadListener listener) {
                    throw new UnsupportedOperationException();
                }
            };
        }

        @Override
        public BufferedReader getReader() {
            return new BufferedReader(new InputStreamReader(getInputStream(), StandardCharsets.UTF_8));
        }

        @Override
        public int getContentLength() {
            return body.length;
        }

        @Override
        public long getContentLengthLong() {
            return body.length;
        }
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.util.List;
import java.util.Objects;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.RetiredPersonException;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Re-date the loaded claim: only a steward may, and only an OPEN or PENDING claim, to a date its person may claim
 *  for (not after their retirement). Its due-by and any figure a statement bound it to stay as they are. Its period
 *  follows the new date: while the sheet numbers claims by period, a claim whose period changes takes the next
 *  number of its new period's sequence (X-<n> for no period), and its old number is never given out again. A
 *  re-date another user's change got to first is refused. */
public class SaveRedate {
    public void save(@Val RedateInput input, @Val Claim loaded, ClaimRepository repository, PersonRepository people,
            PeriodRepository periods, RoleRepository roles, Out<ClaimResponse> saved)
            throws ClaimStatusNotAllowedException, RetiredPersonException {
        if (!Role.STEWARD.equals(roles.of(loaded.sheetId(), input.user()))) {
            throw new ClaimStatusNotAllowedException("Only a steward may re-date a claim.");
        }
        if (!loaded.status().unsettled()) {
            throw new ClaimStatusNotAllowedException("A " + loaded.status()
                    + " claim cannot be re-dated; only an OPEN or PENDING one can.");
        }
        RetiredPersonException.refuse(people.find(loaded.sheetId(), loaded.personId()), input.date());
        String number = loaded.number();
        if (repository.numberingByPeriod(loaded.sheetId())) {
            var all = periods.list(loaded.sheetId());
            if (!Objects.equals(periodOf(all, loaded.date()), periodOf(all, input.date()))) {
                number = repository.nextNumber(loaded.sheetId(), input.date());
            }
        }
        if (!repository.redate(loaded, input.date(), number)) {
            throw new ClaimStatusNotAllowedException("The claim changed meanwhile; load the sheet again.");
        }
        saved.set(ClaimResponse.from(new Claim(loaded.id(), loaded.sheetId(), loaded.personId(), loaded.amount(),
                input.date(), loaded.note(), loaded.status(), number, loaded.settledDue(), loaded.openedBy(),
                loaded.stated(), loaded.statedDue(), loaded.corrects(), loaded.dueBy(), loaded.deferredUntil(),
                loaded.proofs(), loaded.splitFrom(), loaded.lateEntry())));
    }

    /** The name of the period the date falls in (the earliest that holds it, as numbering takes it), else null. */
    private static String periodOf(List<Period> all, LocalDate date) {
        return all.stream().filter(p -> p.contains(date)).map(Period::name).findFirst().orElse(null);
    }
}
