test("cancel statement scenario 3", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "1.50");
  await ui.setSetting(pg_uma, "floor", "2.00");
  await ui.setSetting(pg_uma, "late-pct", "5.00");
  await ui.setSetting(pg_uma, "proof-threshold", "3.00");
  await ui.setSetting(pg_uma, "perm-void", "clerk");
  await ui.setSetting(pg_uma, "grace-days", "0");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50", "from": "2026-03-16"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
  const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "99.95", "date": "2026-02-10"}));
  expect(await ui.editPerson(pg_uma, p_ben, {"grade": "A"})).toBe(true);
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.reassign(pg_vic, c_cam_0, "Ben")).toBe(true);
  expect(await ui.retire(pg_vic, p_ada, "2026-03-15")).toBe(true);
  expect(await ui.claimAction(pg_vic, c_cam_0, "open")).toBe(true);
  await ui.showRetired(pg_vic, true);
  expect(await ui.pasteClaims(pg_vic, "Ada,3.33,2026-03-09,a, b")).toBe(1);
  const c_ada_0 = await ui.claimAt(pg_vic, p_ada, 0);
  expect(await ui.editClaim(pg_vic, c_ada_0, {"amount": "12.50"})).toBe(true);
  await ui.refresh(pg_vic);
  await expect(pg_vic.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("99.95");
  await expect(pg_vic.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("10.00");
  await expect(pg_vic.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-due")).toHaveText("10.00");
  await expect(pg_vic.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_vic.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_vic.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("n/a");
  await expect(pg_vic.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-due")).toHaveText("1.25");
  await expect(pg_vic.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_vic.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_vic.getByTestId("rollup-claimed-total")).toHaveText("99.95");
  await expect(pg_vic.getByTestId("rollup-due-total")).toHaveText("10.00");
  await expect(pg_vic.getByTestId("rollup-overdue-count")).toHaveText("1");
  await expect(pg_vic.getByTestId("rollup-overdue-total")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("header-people-count")).toHaveText("3");
  await expect(pg_vic.getByTestId("header-claims-DRAFT-count")).toHaveText("1");
  await expect(pg_vic.getByTestId("header-claims-OPEN-count")).toHaveText("1");
  await expect(pg_vic.getByTestId("header-claims-PENDING-count")).toHaveText("0");
  await expect(pg_vic.getByTestId("header-claims-SETTLED-count")).toHaveText("0");
